"""NMI evaluation (R15) and the metrics.json writer."""

from __future__ import annotations

import json
import os
from datetime import datetime
from pathlib import Path

import numpy as np
from sklearn.metrics import normalized_mutual_info_score

# The paper cites Vinh et al. (2010) for NMI without stating the normalisation;
# we use the arithmetic average (sklearn default) -- assumption A10.
AVERAGE_METHOD = "arithmetic"


def nmi(y_true, y_pred) -> float:
    return float(normalized_mutual_info_score(y_true, y_pred, average_method=AVERAGE_METHOD))


def write_metrics(path: str | Path, payload: dict) -> str:
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    payload = dict(payload)
    payload["generated_at"] = datetime.now().isoformat(timespec="seconds")
    p.write_text(json.dumps(payload, indent=2))
    return str(p)


def read_json(path: str | Path):
    return json.loads(Path(path).read_text())


def load_selected_config(path: str | Path) -> dict:
    return json.loads(Path(path).read_text())


def repo_root() -> Path:
    return Path(__file__).resolve().parents[1]


def results_dir() -> Path:
    d = repo_root() / "results"
    d.mkdir(parents=True, exist_ok=True)
    return d

